test("applyPasswordOverride: no-op when neither env var is set", () => {
  const config = { users: [{ id: "admin", passwordHash: "unchanged" }] };
  applyPasswordOverride(config, {});
  assert.equal(config.users[0].passwordHash, "unchanged");
